#!/usr/bin/env node
/**
 * Screenshot the table cards generated by scripts/render-table-images.py.
 *
 * Usage: node scripts/screenshot-table-images.mjs
 */

import { chromium } from "playwright";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..");
const preview = path.join(root, "specs", "table-images", "preview.html");
const outputDir = path.join(root, "specs", "table-images");

const cards = [
  "artist-residencies",
  "witchhouse-artists",
  "live-acts",
  "djs",
];

const browser = await chromium.launch();
const page = await browser.newPage({
  viewport: { width: 1200, height: 1000 },
  deviceScaleFactor: 2,
});

await page.goto(pathToFileURL(preview).href);
await page.waitForLoadState("load");

for (const id of cards) {
  const card = page.locator(`#${id}`);
  await card.screenshot({ path: path.join(outputDir, `${id}.png`) });
  console.log(`wrote ${id}.png`);
}

await browser.close();
